pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 duration, uint256 premium) public {
        duration = bound(duration, 1, 10_000 days - 1);
        premium = bound(premium, 0, 1e30);

        ERC20Mock token = new ERC20Mock();
        SigMaker maker = new SigMaker();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        vm.warp(1000);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(0);
        uint256[] memory floorIds = new uint256[](0);

        bool ok = true;
        try c.fillOrder(order, sig, floorIds) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(
            !ok ||
                c.positionExpirations(uint256(c.hashOrder(order))) ==
                block.timestamp + duration,
            "filled order must record its position expiration"
        );
    }

    fallback() external {}
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

contract ERC20Mock {
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}
